<?phpif (!defined('IN_DISCUZ') || !defined('IN_ADMINCP')) {    exit('Access Denied');}$pagesize = $_G['tpp'];//$pagesize = 1;$start_limit = ($page - 1) * $pagesize;$ordercount = C::t("#zeroze007diy#diy007_code")->fetch_count();$multipage = multi($ordercount, $pagesize, $page, ADMINSCRIPT . "?action=plugins&identifier=zeroze007diy&pmod=verifycodenanage&searchsubmit=yes&admin={$_GET['admin']}");showtagheader('div', 'orderlist', TRUE);showformheader('plugins&identifier=zeroze007diy&pmod=verifycodenanage');showtableheader(lang('plugin/zeroze007diy', 'diy007_search_result'));showsubtitle(array(	'',	'UID' ,	lang('plugin/zeroze007diy', 'code') ,	lang('plugin/zeroze007diy', 'status') ,	lang('plugin/zeroze007diy', 'result') ,	lang('plugin/zeroze007diy', 'uploaderPrefix') ,	lang('plugin/zeroze007diy', 'downloaderPrefix') ,	lang('plugin/zeroze007diy', 'uploaderPrefixName') ,	lang('plugin/zeroze007diy', 'downloaderPrefixName') ,	lang('plugin/zeroze007diy', 'remark') ,	lang('plugin/zeroze007diy', 'dateline')));//查询foreach ((C::t("#zeroze007diy#diy007_code")->fetch_limit($start_limit, ($start_limit + $pagesize))) as $code) {	showtablerow('', '', array(		"<input class=\"checkbox\" type=\"checkbox\" value=\"$code[Code]\">",		$code['uid'],		$code['Code'],		$code['Status'],		$code['Result'] == true ? lang('plugin/zeroze007diy', 'enable') : lang('plugin/zeroze007diy', 'disnable'),		$code['UploaderPrefix'] == true ? lang('plugin/zeroze007diy', 'have') : lang('plugin/zeroze007diy', 'nohave'),		$code['DownloaderPrefix'] == true ? lang('plugin/zeroze007diy', 'have') : lang('plugin/zeroze007diy', 'nohave'),		$code['UploaderPrefixName'],		$code['DownloaderPrefixName'],		$code['remark'],		date("Y-m-d H:i:s", $code['Dateline'])	));}showsubmit('', '', '', '<a href="#" onclick="$(\'orderlist\').style.display=\'none\';$(\'codesearch\').style.display=\'\';">' . cplang('research') . '</a>', $multipage);showtablefooter();showformfooter();showtagfooter